import { ref } from "vue"
import { projectAuth } from "../Firebase/config"
import { createUserWithEmailAndPassword, updateProfile } from 'firebase/auth'

const error = ref(null);

const signup = async (email, password, displayName) => {
    error.value = null

    console.log(`Data: `,email,displayName)

    try {
        const response = await createUserWithEmailAndPassword(projectAuth, email, password)
            // .then((userCredential) => {
            //     // Signed up 
            //     const user = userCredential.user;
            //     // ...
            // })
        await updateProfile(response.user, { displayName: displayName })
        if (!response) {
            throw new Error('Could not complete the signup')
        }
        console.log(`User signed up: `, response.user)
        error.value = null
    } catch(err) {
        // const errorCode = err.code;
        // const errorMessage = err.message;
        error.value = err.message
        console.log(`Error on signup: `,err.message)
    }
}

const useSignup = () => {
  return { error, signup }
}

export default useSignup