import { ref, watchEffect } from "vue"
import { projectAuth, projectFirestore } from "../Firebase/config"
import { collection, limit, onSnapshot, orderBy, query } from "firebase/firestore"

const getCollection = (collectionName) => {
    const documents = ref(null)
    const error = ref(null)

    const q = query(collection(projectFirestore, collectionName), orderBy('createdAt', 'desc'), limit(10))
    const unsubscribe = onSnapshot(q, (querySnapshot) => {
        console.log(`Snapshot`)
        let results = []
        querySnapshot.forEach((doc) => {
            doc.data().createdAt && results.push({ ...doc.data(), id: doc.id })
        })
        documents.value = results.reverse()
        // documents.value = results
        error.value = null
    })

    // unsubscribe from the snapshot listener when the component is unmounted (prevent multiple snapshots from being set up)
    watchEffect((onInvalidate) => {
        onInvalidate(() => unsubscribe())
    })

    return { documents, error }
}

export default getCollection